$string['setting_redirect_uri_desc'] = 'OAuth ಪ್ರಕ್ರಿಯೆ ಯಶಸ್ವಿಯಾಗಬೇಕಾದರೆ Microsoft Azure ಮತ್ತು Google Cloud Console ಎರಡರಲ್ಲೂ ಇದೇ URL ಅನ್ನು ಅಧಿಕೃತ ರೀಡೈರೆಕ್ಟ್ URI ಆಗಿ ಸೇರಿಸಿರಬೇಕು. ರೀಡ್-ಓನ್ಲಿ — <code>$CFG-&gt;wwwroot</code> ನಿಂದ ಪಡೆಯಲಾಗಿದೆ.';
$string['setting_scaffolding_notice'] = 'OAuth ಫೇಸ್ 2.1 ಲೈವ್ ಟೋಕನ್ ಎಕ್ಸ್‌ಚೇಂಜ್ ಅನ್ನು ಮಾಸ್ಟರ್ ಫೀಚರ್ ಫ್ಲ್ಯಾಗ್ <code>sentientia.calendar_sync.oauth.enabled</code> ಹಿಂದೆ (ಡೀಫಾಲ್ಟ್ OFF) ನೀಡುತ್ತದೆ. ಕೆಳಗಿನ ಕ್ರೆಡೆನ್ಶಿಯಲ್‌ಗಳನ್ನು ತುಂಬಿದರೆ ಇಂಟಿಗ್ರೇಶನ್ ಸಿದ್ಧವಾಗುತ್ತದೆ; ಒಬ್ಬ ಕಸ್ಟಮರ್‌ಗೆ ಫ್ಲ್ಯಾಗ್ ON ಮಾಡಿದಾಗ ಅದು ಆ್ಯಕ್ಟಿವೇಟ್ ಆಗುತ್ತದೆ. ಟೆಸ್ಟ್‌ಗಳು ಮಾಕ್ ಎಂಡ್‌ಪಾಯಿಂಟ್‌ಗಳನ್ನು ಬಳಸುತ್ತವೆ — CI ಯಿಂದ ಯಾವುದೇ ಲೈವ್ OAuth ಕಾಲ್‌ಗಳು ರನ್ ಆಗುವುದಿಲ್ಲ.';
$string['privacy:metadata'] = 'Sentientia LMS ಕ್ಯಾಲೆಂಡರ್ ಸಿಂಕ್ ಪ್ರತಿ ಯೂಸರ್‌ಗೆ ಒಂದು ಸೀಕ್ರೆಟ್ ಸಬ್‌ಸ್ಕ್ರಿಪ್ಷನ್ ಟೋಕನ್ ಅನ್ನು ಸಂಗ್ರಹಿಸುತ್ತದೆ. ಕ್ಯಾಲೆಂಡರ್ ಕ್ಲೈಂಟ್‌ಗಳು ಈ ಟೋಕನ್ ಬಳಸಿ ಯೂಸರ್‌ನ ವೈಯಕ್ತಿಕ ಫೀಡ್ ಅನ್ನು ಪಡೆಯುತ್ತವೆ. ಫೇಸ್ 2 OAuth ಎನೇಬಲ್ ಆದಾಗ, ಇದು ಯೂಸರ್‌ಗಾಗಿ ಎನ್‌ಕ್ರಿಪ್ಟ್ ಮಾಡಿದ Microsoft 365 ಮತ್ತು/ಅಥವಾ Google Calendar OAuth ಟೋಕನ್‌ಗಳನ್ನೂ ಸಂಗ್ರಹಿಸುತ್ತದೆ. ಯಾವುದೇ ಕೋರ್ಸ್ ಕಂಟೆಂಟ್ ಅಥವಾ ಥರ್ಡ್-ಪಾರ್ಟಿ ಡೇಟಾವನ್ನು ಸಂಗ್ರಹಿಸುವುದಿಲ್ಲ — ಕೇವಲ ಕ್ರೆಡೆನ್ಶಿಯಲ್‌ಗಳು ಮತ್ತು ಆಡಿಟ್ ಮೆಟಾಡೇಟಾ (ಕೊನೆಯದಾಗಿ ಬಳಸಿದ ಸಮಯ, IP, ಎಣಿಕೆ).';
